[HttpGet("{id:guid}/items")]
public ActionResult<PagedResult<ItemDto>> ListItems(
    [FromRoute] Guid id,
    [FromQuery] int page = 1,
    [FromQuery] int pageSize = 20,
    [FromHeader(Name = "X-Correlation-Id")] string? correlationId,
    [FromServices] IItemService items)
{
    var result = items.ListForOrder(id, page, pageSize);
    return Ok(result);
}

public sealed record OrderQuery(
    int Page = 1,
    int PageSize = 20,
    OrderStatus? Status = null,
    string? Sort = "createdDesc");

[HttpGet]
public ActionResult<PagedResult<OrderDto>> GetOrders(
    [AsParameters] OrderQuery query,
    [FromServices] IOrderService orders)
    => Ok(orders.Search(query));

// Minimal API — identical pattern:
app.MapGet("/api/orders", ([AsParameters] OrderQuery query, IOrderService svc)
    => Results.Ok(svc.Search(query)));

public sealed record TenantOrderQuery(
    [FromRoute] string TenantId,
    [FromQuery] int Page = 1,
    [FromQuery] DateOnly? From = null);

[HttpGet("/api/{tenantId}/orders")]
public IActionResult GetTenantOrders([AsParameters] TenantOrderQuery q)
    => Ok(new { q.TenantId, q.Page, q.From });

// Route property TenantId binds from {tenantId}
// Query properties bind from ?page=1&from=2024-01-01

